parameters.jsCode:
const isReal = (i) => i.json && Object.keys(i.json).length > 0;
const income = $('Read Income').all().filter(isReal).map(i => i.json);
const expenses = $('Read Expenses').all().filter(isReal).map(i => i.json);

// Report month: previous month when run on the 1st, otherwise current month-to-date
const now = new Date();
let y = now.getFullYear();
let m = now.getMonth();
if (now.getDate() === 1) { m -= 1; if (m < 0) { m = 11; y -= 1; } }
const monthKey = y + '-' + String(m + 1).padStart(2, '0');

function toNum(v) {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v || '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
}
function monthOf(v) {
  if (typeof v === 'number') {
    const d = new Date(Math.round((v - 25569) * 86400000));
    return d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
  }
  const s = String(v || '').trim();
  const iso = s.match(/^(\d{4})-(\d{1,2})/);
  if (iso) return iso[1] + '-' + iso[2].padStart(2, '0');
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
  return '';
}
const round = (n) => Math.round(n * 100) / 100;

const inc = income.filter(r => monthOf(r.date) === monthKey);
const exp = expenses.filter(r => monthOf(r.date) === monthKey);

const totalIncome = inc.reduce((s, r) => s + toNum(r.total_usd), 0);
const totalExpenses = exp.reduce((s, r) => s + toNum(r.total_usd), 0);
const net = totalIncome - totalExpenses;
const margin = totalIncome > 0 ? (net / totalIncome) * 100 : 0;

const byCat = {};
for (const r of exp) { const c = r.category || 'Other Expense'; byCat[c] = (byCat[c] || 0) + toNum(r.total_usd); }
const known = ['Tools & Software', 'Salaries & Payroll', 'Office & Rent', 'Utilities & Bills', 'Tax'];
const otherExp = totalExpenses - known.reduce((s, k) => s + (byCat[k] || 0), 0);

const byClient = {};
for (const r of inc) { const c = r.client || 'Unknown'; byClient[c] = (byClient[c] || 0) + toNum(r.total_usd); }
const clientsSorted = Object.entries(byClient).sort((a, b) => b[1] - a[1]);
const topClient = clientsSorted.length ? clientsSorted[0][0] + ' ($' + round(clientsSorted[0][1]) + ')' : '-';

const byVendor = {};
for (const r of exp) { const v = r.vendor || 'Unknown'; byVendor[v] = (byVendor[v] || 0) + toNum(r.total_usd); }
const topVendors = Object.entries(byVendor).sort((a, b) => b[1] - a[1]).slice(0, 5);

const unpaid = income.filter(r => String(r.status || '').toLowerCase() === 'unpaid');
const unpaidTotal = unpaid.reduce((s, r) => s + toNum(r.total_usd), 0);

const lines = [];
lines.push('Agency finance numbers for ' + monthKey + ' (USD)');
lines.push('Total income: ' + round(totalIncome) + ' from ' + inc.length + ' invoices');
lines.push('Total expenses: ' + round(totalExpenses) + ' from ' + exp.length + ' documents');
lines.push('Net profit: ' + round(net) + ' | Profit margin: ' + round(margin) + '%');
lines.push('Expenses by category: ' + (Object.entries(byCat).map(e => e[0] + ' ' + round(e[1])).join(', ') || 'none'));
lines.push('Income by client: ' + (clientsSorted.map(e => e[0] + ' ' + round(e[1])).join(', ') || 'none'));
lines.push('Top 5 vendors/tools by spend: ' + (topVendors.map(e => e[0] + ' ' + round(e[1])).join(', ') || 'none'));
lines.push('Unpaid client invoices (all time): ' + unpaid.length + ' totalling ' + round(unpaidTotal) + (unpaid.length ? ' - ' + unpaid.map(r => (r.client || 'Unknown') + ' ' + round(toNum(r.total_usd))).join(', ') : ''));

return [{ json: {
  month: monthKey,
  total_income: round(totalIncome),
  total_expenses: round(totalExpenses),
  net_profit: round(net),
  profit_margin_pct: round(margin),
  tools_software: round(byCat['Tools & Software'] || 0),
  salaries: round(byCat['Salaries & Payroll'] || 0),
  office_rent: round(byCat['Office & Rent'] || 0),
  utilities_bills: round(byCat['Utilities & Bills'] || 0),
  tax: round(byCat['Tax'] || 0),
  other_expenses: round(otherExp),
  unpaid_client_invoices: round(unpaidTotal),
  top_client: topClient,
  summary_text: lines.join('\n')
} }];
